1	import { expect, test } from "@playwright/test";
2	import { DOCK_COLOR, FOG_COLOR, LAND_COLORS, SEA_COLOR, SHOAL_COLOR } from "../../apps/web/src/palette.js";
3	import { compassHeading, dockLabel, isNavigable, seaMap, shipTuning, SIGHT_RADIUS_TILES, Terrain, terrainAt } from "../../packages/content/src/index.js";
4	import {
5	  attachScreenshot,
6	  clearCourse,
7	  colourAt,
8	  createMatch,
9	  dockHintsSeen,
10	  drawnIds,
11	  fogRevealed,
12	  joinMatch,
13	  listedIds,
14	  minimapShows,
15	  onCanvas,
16	  ownColour,
17	  ownDrawnPosition,
18	  place,
19	  readout,
20	  recordDockHints,
21	  sailTo,
22	  selfId,
23	  shipsOnCanvas,
24	  tileColourShare,
25	  TILE,
26	  turnTo,
27	} from "./helpers.js";
28	
29	// Sailing with the keyboard takes real time, and a software-rendered browser on a busy machine reads the HUD slowly.
30	test.describe.configure({ timeout: 180_000 });
31	
32	const centre = (tileX: number, tileY: number) => ({ x: tileX * TILE + TILE / 2, y: tileY * TILE + TILE / 2 });
33	const SIGHT = SIGHT_RADIUS_TILES * TILE;
34	
35	test("sail around a shoal to an island dock and dock there [scenario:sail-and-dock]", async ({ page, request }, testInfo) => {
36	  // Palm Key's south dock sits in a corner of the shore: land beside it to the west in its row, open sea to the east,
37	  // and the coast running on east of it one row further north. A shoal bar lies across the water south of it.
38	  const palm = seaMap.islands.findIndex((island) => island.name === "Palm Key");
39	  const dock = seaMap.docks.find((each) => each.island === palm && each.side === "S")!;
40	  expect(terrainAt(seaMap, dock.tileX - 1, dock.tileY)).toBe(Terrain.Land);
41	  for (let tileX = dock.tileX + 1; tileX <= dock.tileX + 3; tileX++) expect(terrainAt(seaMap, tileX, dock.tileY)).toBe(Terrain.Sea);
42	  for (let tileX = dock.tileX; tileX <= dock.tileX + 4; tileX++) expect(terrainAt(seaMap, tileX, dock.tileY - 1)).toBe(Terrain.Land);
43	  const start = { tileX: dock.tileX, tileY: dock.tileY + 14 };
44	  // The straight course from the start to the dock runs over the shoal.
45	  const shoalOnCourse = Array.from({ length: start.tileY - dock.tileY }, (_, step) => terrainAt(seaMap, dock.tileX, dock.tileY + 1 + step));
46	  expect(shoalOnCourse).toContain(Terrain.Shoal);
47	  const shoalRows = shoalOnCourse.flatMap((kind, step) => (kind === Terrain.Shoal ? [dock.tileY + 1 + step] : []));
48	  let shoalEnd = dock.tileX;
49	  while (terrainAt(seaMap, shoalEnd + 1, shoalRows[0]!) === Terrain.Shoal) shoalEnd++;
50	
51	  const code = await createMatch(page);
52	  await place(request, page, code, start.tileX, start.tileY, compassHeading("N"));
53	  await expect(page.getByTestId("hud-dock")).toHaveText("at sea");
54	  // Round the east end of the shoal, then come up to the last waypoint: two tiles east of the dock, toward the open
55	  // side, and three tiles out.
56	  const approach = { tileX: dock.tileX + 2, tileY: dock.tileY + 3 };
57	  const waypoints = [
58	    { tileX: shoalEnd + 3, tileY: shoalRows.at(-1)! + 2 },
59	    { tileX: shoalEnd + 3, tileY: shoalRows[0]! - 2 },
60	    { tileX: approach.tileX, tileY: shoalRows[0]! - 2 },
61	    approach,
62	  ];
63	  // sailTo steers in straight lines: every leg is open sea for a hull's width.
64	  [start, ...waypoints].slice(1).forEach((point, index) => {
65	    const from = [start, ...waypoints][index]!;
66	    expect(clearCourse(centre(from.tileX, from.tileY), centre(point.tileX, point.tileY)), `leg ${index}`).toBe(true);
67	  });
68	
69	  // The minimap's fog before sailing. Wait until the ship is drawn at the start: the jump from the spawn slot is drawn
70	  // as a fast glide that clears fog on its way, so only what is still fogged now can be cleared by sailing. The
71	  // candidates are open-sea tiles out of sight of the start but well within sight of a waypoint (so their minimap
72	  // pixel, which blends a tile with its neighbours, turns wholly to sea); the ones still fogged must all clear. They
73	  // lie on both sides of the course, so a glide along one line never clears them all.
74	  await expect.poll(() => ownDrawnPosition(page)).toEqual(centre(start.tileX, start.tileY));
75	  const fogAtStart = await fogRevealed(page);
76	  const beside: { tileX: number; tileY: number }[] = [];
77	  const wellWithinSight = SIGHT_RADIUS_TILES - 2;
78	  for (let tileY = dock.tileY - SIGHT_RADIUS_TILES; tileY <= start.tileY; tileY++) {
79	    for (let tileX = dock.tileX - SIGHT_RADIUS_TILES; tileX <= shoalEnd + SIGHT_RADIUS_TILES + 3; tileX++) {
80	      const openSea = [-1, 0, 1].every((dy) => [-1, 0, 1].every((dx) => terrainAt(seaMap, tileX + dx, tileY + dy) === Terrain.Sea));
81	      const outOfSightAtStart = (tileX - start.tileX) ** 2 + (tileY - start.tileY) ** 2 > (SIGHT_RADIUS_TILES + 1) ** 2;
82	      const nearRoute = waypoints.some((point) => (tileX - point.tileX) ** 2 + (tileY - point.tileY) ** 2 <= wellWithinSight ** 2);
83	      const offTheBerth = (tileX - dock.tileX) ** 2 + (tileY - dock.tileY) ** 2 >= 5 * 5;
84	      if (openSea && outOfSightAtStart && nearRoute && offTheBerth) beside.push({ tileX, tileY });
85	    }
86	  }
87	  expect(beside.some((tile) => tile.tileX < start.tileX) && beside.some((tile) => tile.tileX > start.tileX)).toBe(true);
88	  const foggedAtStart = await minimapShows(page, beside, FOG_COLOR);
89	  const stillFogged = beside.filter((_, index) => foggedAtStart[index]);
90	  expect(stillFogged.length).toBeGreaterThan(0);
91	
92	  // Round the shoal with the keyboard.
93	  const visited: { x: number; y: number }[] = [];
94	  const record = (ship: { x: number; y: number }) => visited.push(ship);
95	  const fogAlong = [fogAtStart];
96	  for (const point of waypoints) {
97	    await sailTo(page, centre(point.tileX, point.tileY), { within: TILE, onReadout: record });
98	    fogAlong.push(await fogRevealed(page));
99	  }
100	  const berth = centre(dock.tileX, dock.tileY);
101	
102	  // The run in: at rest, turn to a fixed heading one or two units west of north, toward the land beside the dock, then
103	  // hold ahead and E together. The ship grounds on the coast past the dock and slides along it into the corner, stops in
104	  // the dock tile and moors; nothing is timed and no key is released on the way.
105	  const runStart = await turnTo(page, [compassHeading("N") - 2, compassHeading("N") - 1]);
106	  // It starts the run 1–3 tiles east of the dock and 2–4 tiles out, where the simulation's sweep shows it moors.
107	  expect(Math.floor(runStart.x / TILE) - dock.tileX).toBeGreaterThanOrEqual(1);
108	  expect(Math.floor(runStart.x / TILE) - dock.tileX).toBeLessThanOrEqual(3);
109	  expect(Math.floor(runStart.y / TILE) - dock.tileY).toBeGreaterThanOrEqual(2);
110	  await recordDockHints(page);
111	  await page.keyboard.down("ArrowUp");
112	  await page.keyboard.down("KeyE");
113	  await expect(page.getByTestId("hud-dock")).toHaveText(dockLabel(seaMap, dock.id), { timeout: 30_000 });
114	  // Let go of ahead first: while E is held the ship stays moored whatever the throttle does.
115	  await page.keyboard.up("ArrowUp");
116	  await page.keyboard.up("KeyE");
117	  expect(dockLabel(seaMap, dock.id)).toBe("Palm Key, south dock");
118	  // On the way in, beside the dock, the HUD said how to dock there; moored, it says nothing.
119	  expect(await dockHintsSeen(page)).toContainEqual(expect.stringMatching(new RegExp(`to dock at ${dockLabel(seaMap, dock.id)}$`)));
120	  await expect(page.getByTestId("hud-dock-hint")).toHaveText("");
121	
122	  // The ship stops at the dock and stays there.
123	  const self = await selfId(page);
124	  const moored = (await readout(page, self))!;
125	  expect(moored).toMatchObject({ ...berth, speed: 0, dock: dock.id });
126	  await page.waitForTimeout(500);
127	  expect(await readout(page, self)).toEqual(moored);
128	  // It went round the shoal, never over it.
129	  expect(visited.length).toBeGreaterThan(10);
130	  for (const point of visited) expect(isNavigable(seaMap, Math.floor(point.x / TILE), Math.floor(point.y / TILE))).toBe(true);
131	  expect(visited.some((point) => Math.floor(point.x / TILE) > shoalEnd)).toBe(true);
132	  await expect.poll(() => shipsOnCanvas(page)).toEqual([self]);
133	
134	  // The tile map is on the canvas: land, the shoal bar, the island's other dock and open sea each show their
135	  // placeholder colour, sampled at the tile through the camera's scroll.
136	  const island = seaMap.islands[palm]!;
137	  const otherDock = seaMap.docks.find((each) => each.island === palm && each.id !== dock.id)!;
138	  const tiles = [
139	    { name: "land", tileX: dock.tileX, tileY: dock.tileY - 4, kind: Terrain.Land, color: LAND_COLORS[island.theme] },
140	    { name: "shoal", tileX: dock.tileX, tileY: shoalRows[0]!, kind: Terrain.Shoal, color: SHOAL_COLOR },
141	    { name: "dock", tileX: otherDock.tileX, tileY: otherDock.tileY, kind: Terrain.Dock, color: DOCK_COLOR },
142	    { name: "sea", tileX: dock.tileX, tileY: dock.tileY + 2, kind: Terrain.Sea, color: SEA_COLOR },
143	  ];
144	  for (const each of tiles) {
145	    expect(terrainAt(seaMap, each.tileX, each.tileY), each.name).toBe(each.kind);
146	    await expect.poll(() => tileColourShare(page, each.tileX, each.tileY, each.color), { message: `${each.name} tile` }).toBeGreaterThan(0.75);
147	  }
148	  // And not by accident: land is not drawn in the shoal colour, nor the shoal in the sea colour.
149	  expect(await tileColourShare(page, tiles[0]!.tileX, tiles[0]!.tileY, SHOAL_COLOR)).toBe(0);
150	  expect(await tileColourShare(page, tiles[1]!.tileX, tiles[1]!.tileY, SEA_COLOR)).toBe(0);
151	
152	  // The fog cleared along the sailed path: the revealed count grew leg by leg, and every candidate tile that was still
153	  // fogged at the start now shows the sea on the minimap.
154	  expect(fogAlong).toEqual([...fogAlong].sort((a, b) => a - b));
155	  expect(fogAlong.at(-1)!).toBeGreaterThan(fogAtStart);
156	  expect(await minimapShows(page, stillFogged, SEA_COLOR)).toEqual(stillFogged.map(() => true));
157	
158	  await attachScreenshot(page, testInfo, "sail-and-dock");
159	
160	  // Any throttle casts off.
161	  await page.keyboard.down("ArrowDown");
162	  await expect(page.getByTestId("hud-dock")).toHaveText("at sea");
163	  await page.keyboard.up("ArrowDown");
164	});
165	
166	test("ships out of sight are neither listed nor drawn until one sails within sight [scenario:out-of-sight]", async ({ browser, request }, testInfo) => {
167	  const hostContext = await browser.newContext();
168	  const guestContext = await browser.newContext();
169	  try {
170	    const host = await hostContext.newPage();
171	    const guest = await guestContext.newPage();
172	    const code = await createMatch(host);
173	    await joinMatch(guest, code);
174	    await expect(guest.getByTestId("hud-players")).toHaveText("2");
175	
176	    // Thirteen tiles apart on the open row three tiles south of the hub and of the wall running east from it: the host
177	    // beside the gap in the wall south of the hub, the guest east of it, facing the host. Out of sight, but where each
178	    // would be on the other's screen. South of the row is open water: the guest turns about into it (sailTo turns
179	    // left, in a circle about three tiles across) and sails away east.
180	    const { hub } = seaMap;
181	    const row = hub.tileY + 3;
182	    const [hostTile, guestTile] = [{ tileX: hub.tileX + 1, tileY: row }, { tileX: hub.tileX + 14, tileY: row }];
183	    for (let tileY = row + 1; tileY <= row + 4; tileY++) expect(clearCourse(centre(hostTile.tileX + 2, tileY), centre(guestTile.tileX, tileY))).toBe(true);
184	    const away = { tileX: guestTile.tileX + SIGHT_RADIUS_TILES, tileY: row };
185	    expect(clearCourse(centre(hostTile.tileX, row), centre(away.tileX, row))).toBe(true);
186	    await place(request, host, code, hostTile.tileX, row, compassHeading("E"));
187	    await place(request, guest, code, guestTile.tileX, row, compassHeading("W"));
188	    const hostId = await selfId(host);
189	    const guestId = await selfId(guest);
190	    const hostShip = (await readout(host, hostId))!;
191	    const guestStart = (await readout(guest, guestId))!;
192	    expect((guestStart.x - hostShip.x) ** 2).toBeGreaterThan(SIGHT ** 2);
193	    expect(guestStart.x - hostShip.x).toBeGreaterThanOrEqual(12 * TILE);
194	    expect(guestStart.x - hostShip.x).toBeLessThanOrEqual(13 * TILE);
195	    const [hostColour, guestColour] = [await ownColour(host), await ownColour(guest)];
196	    // The camera follows each ship unclamped, so the other ship's position is on each canvas: were it drawn, it would
197	    // show.
198	    for (const [page, own, other] of [[host, hostShip, guestStart], [guest, guestStart, hostShip]] as const) {
199	      await expect.poll(async () => (await onCanvas(page, own.x, own.y)).offCentre).toBeLessThanOrEqual(1);
200	      expect((await onCanvas(page, other.x, other.y)).inside).toBe(true);
201	    }
202	
203	    const expectApart = async () => {
204	      await expect.poll(() => listedIds(guest)).toEqual([guestId]);
205	      await expect.poll(() => listedIds(host)).toEqual([hostId]);
206	      await expect.poll(() => drawnIds(guest)).toEqual([guestId]);
207	      await expect.poll(() => drawnIds(host)).toEqual([hostId]);
208	      // Nothing of the other ship's colour where it actually is, on either canvas.
209	      const guestShip = (await readout(guest, guestId))!;
210	      expect(await colourAt(guest, hostShip.x, hostShip.y, hostColour)).toBe(false);
211	      expect(await colourAt(host, guestShip.x, guestShip.y, guestColour)).toBe(false);
212	      // Both still know there are two players.
213	      await expect(host.getByTestId("hud-players")).toHaveText("2");
214	    };
215	    await expectApart();
216	
217	    // The guest sails toward the host with the keyboard until the host comes into sight.
218	    await guest.keyboard.down("ArrowUp");
219	    await expect.poll(() => listedIds(guest), { timeout: 15_000, intervals: [50] }).toEqual([hostId, guestId].sort());
220	    await guest.keyboard.up("ArrowUp");
221	    const closing = (await readout(guest, guestId))!;
222	    expect(Math.hypot(closing.x - hostShip.x, closing.y - hostShip.y)).toBeLessThanOrEqual(SIGHT + 3 * shipTuning.maxSpeed);
223	    await expect.poll(() => listedIds(host)).toEqual([hostId, guestId].sort());
224	    await expect.poll(() => shipsOnCanvas(guest)).toEqual([hostId, guestId].sort());
225	    await expect.poll(() => shipsOnCanvas(host)).toEqual([hostId, guestId].sort());
226	
227	    // It turns about and sails away east until the host drops out of sight again.
228	    await sailTo(guest, centre(away.tileX, away.tileY), { until: async () => !(await listedIds(guest)).includes(hostId) });
229	    const gone = (await readout(guest, guestId))!;
230	    expect(Math.hypot(gone.x - hostShip.x, gone.y - hostShip.y)).toBeGreaterThan(SIGHT - 3 * shipTuning.maxSpeed);
231	    // Let it coast to a stop out of sight before checking both views.
232	    await expect.poll(async () => (await readout(guest, guestId))!.speed, { timeout: 10_000 }).toBe(0);
233	    await expectApart();
234	
235	    await attachScreenshot(guest, testInfo, "out-of-sight");
236	  } finally {
237	    await hostContext.close();
238	    await guestContext.close();
239	  }
240	});
